import json
from pathlib import Path

SUB = '9701-3.2'
K1, K2 = SUB+'.1', SUB+'.2'
root = Path(__file__).resolve().parents[3]
note = 'Subjects/9701 Chemistry/03 Chemical bonding/3.2 Ionic bonding.md'
mis = [
 {'id':'m1','kc':K1,'statement':'Ionic bonding is electron transfer.','refutation':'Electron transfer forms ions; the bond is the electrostatic attraction between oppositely charged ions.','contrast':'Formation of ions versus attraction between ions.','source':'ER 9701 w22 P22 Q1'},
 {'id':'m2','kc':K2,'statement':'A metal atom gains electrons to form its ion.','refutation':'Metal atoms lose electrons to form cations; non-metal atoms gain them to form anions.','contrast':'Na forms Na⁺ while Cl forms Cl⁻.','source':'research'},
 {'id':'m3','kc':K2,'statement':'An ionic solid consists of separate molecules or ion pairs.','refutation':'Its ions repeat throughout a giant ionic lattice.','contrast':'Formula units give ratios, not discrete molecules.','source':'research'},
]
items=[]
def add(kc, command, stem, options, answer, explanation, wrong, difficulty=2):
 assert answer in options and len(options)==4 and all(x in options for x in wrong)
 i=len(items)+1
 items.append({'id':f'{SUB}-i{i:02}','kcs':[kc],'kind':'mcq','difficulty':difficulty,'command_word':command,'source':{'type':'generated'},'stem':stem,'options':options,'answer':answer,'distractors':wrong,'shuffle':True,'marks':1,'explanation':explanation,'hints':['Think about which particles are present.','Use the charges and electron changes to eliminate options.','Check the meaning of the key term before selecting.']})
add(K1,'Define','Which statement defines ionic bonding?',{'A':'Transfer of electrons from one atom to another','B':'Electrostatic attraction between oppositely charged ions','C':'Attraction between nuclei and shared electrons','D':'Attraction between neutral molecules'},'B','The bond is the electrostatic attraction between cations and anions. A describes one route to ion formation, not the bond.',{'A':'m1'})
add(K1,'Identify','Which pair of particles attracts in an ionic bond?',{'A':'Two cations','B':'Two anions','C':'A cation and an anion','D':'Two neutral atoms'},'C','Opposite ionic charges attract; like charges repel.',{})
add(K1,'State','What is a cation?',{'A':'A negatively charged ion','B':'A positively charged ion','C':'An electron pair','D':'A neutral atom'},'B','A cation carries positive charge, commonly after a metal atom loses electrons.',{'A':'m2'})
add(K1,'State','What is an anion?',{'A':'A positively charged ion','B':'A proton','C':'A negatively charged ion','D':'A neutral molecule'},'C','An anion carries negative charge, commonly after a non-metal atom gains electrons.',{})
add(K1,'Explain','A student says electron transfer is itself an ionic bond. Which response is correct?',{'A':'Yes, because transferred electrons join two nuclei','B':'No, transfer can produce ions; attraction between opposite ions is the bond','C':'Yes, because ions are neutral','D':'No, because ionic solids contain only atoms'},'B','Electron transfer can create the ions, whereas electrostatic attraction between opposite ions constitutes ionic bonding.',{'A':'m1'},4)
add(K1,'Deduce','Which interaction is attractive?',{'A':'Na⁺ with Mg²⁺','B':'Cl⁻ with O²⁻','C':'Mg²⁺ with O²⁻','D':'Na⁺ with Ca²⁺'},'C','Mg²⁺ and O²⁻ have opposite charges and attract electrostatically.',{})
add(K2,'Describe','Which ions make up sodium chloride?',{'A':'Na⁺ and Cl⁻','B':'Na⁻ and Cl⁺','C':'Na²⁺ and Cl²⁻','D':'Neutral Na and Cl atoms'},'A','Sodium loses one electron to form Na⁺; chlorine gains one to form Cl⁻.',{'B':'m2'})
add(K2,'Describe','Which ions make up magnesium oxide?',{'A':'Mg⁺ and O⁻','B':'Mg²⁺ and O²⁻','C':'Mg²⁻ and O²⁺','D':'Mg atoms and O atoms'},'B','Magnesium loses two electrons and oxygen gains two, forming Mg²⁺ and O²⁻.',{'C':'m2'})
add(K2,'Deduce','Which ions and ratio occur in calcium fluoride?',{'A':'Ca⁺ and F⁻, 1:1','B':'Ca²⁺ and F²⁻, 1:1','C':'Ca²⁺ and F⁻, 1:2','D':'Ca⁻ and F⁺, 1:2'},'C','One Ca²⁺ balances two F⁻ ions, giving CaF₂.',{'D':'m2'})
add(K2,'Describe','Which description fits solid sodium chloride?',{'A':'Separate NaCl molecules','B':'A giant lattice of alternating oppositely charged ions','C':'A lattice of neutral atoms','D':'Pairs of ions with no further attraction'},'B','Na⁺ and Cl⁻ extend in a giant ionic lattice, with electrostatic attractions throughout.',{'A':'m3','D':'m3'})
add(K2,'Explain','Why does the formula CaF₂ contain two fluoride ions per calcium ion?',{'A':'Each calcium ion has charge 2+ and each fluoride ion has charge 1−','B':'Each calcium ion has charge 1+','C':'Fluoride ions are neutral','D':'Two calcium ions share one fluoride ion'},'A','Two F⁻ ions balance the charge of one Ca²⁺ ion.',{},4)
add(K2,'Compare','What is common to sodium chloride, magnesium oxide and calcium fluoride?',{'A':'Each consists of separate molecules','B':'Each has only singly charged ions','C':'Each has electrostatic attraction between cations and anions in a giant lattice','D':'Each has the same cation:anion ratio'},'C','All three have giant ionic lattices held by attraction between opposite ions. Their charge and number ratios differ.',{'A':'m3'},4)
past=[('9701_w25_13_q16','CAIE 9701 · Nov 2025 · P13 · Q16')]
stem='The atomic radii and ionic radii for three elements in Period 3 are shown. / atomic radius / nm / ionic radius / nm / element X / 0.118 / 0.053 / element Y / 0.099 / 0.180 / element Z / 0.160 / 0.072 / Using this data, which statement is correct?'
opts={'A':'Element X has lower electrical conductivity than element Y.','B':'Element Y has a higher melting point than element X.','C':'Element Y and element Z react to form an ionic compound.','D':'Element Z forms ionic compounds by gaining electrons.'}
for n,(ref,cite) in enumerate(past,1):
 items.append({'id':f'{SUB}-p{n:02}','kcs':[K1],'kind':'mcq','difficulty':4,'command_word':'Deduce','source':{'type':'past','ref':ref},'stem':stem,'options':opts,'answer':'C','distractors':{'D':'m2'},'image':f'Assets/mcq/{ref}.png','marks':1,'explanation':'Y forms a larger anion while Z forms a smaller cation, so they can form an ionic compound. D is wrong because Z becomes smaller on ion formation: it loses electrons rather than gaining them.','hints':['Compare each ionic radius with its atomic radius.','A smaller ion indicates electron loss; a larger ion indicates electron gain.','Classify Y and Z by their radius changes.']})
items.append({'id':SUB+'-p03','kcs':[K2],'kind':'mcq','difficulty':3,'command_word':'Identify','source':{'type':'past','ref':'9701_s25_11_q8'},'stem':'Which diagram represents the lattice structure of sodium chloride? / Na / Cl / Na / Cl / Na / Cl / Na / Cl / Na / Cl / Na / Cl / Na / Cl / Na / Cl','options':{'A':'+ – + – + – + – + – + – + – + –','B':'– + + – + + + + + + + + + + + + + + + + – + – + – + – + – + – +','C':'','D':'key Cl Na – + = chlorine atom = sodium atom = chloride ion = sodium ion – – – – – – – – – – – – – – – – – – – –'},'answer':'B','distractors':{'D':'m3'},'image':'Assets/mcq/9701_s25_11_q8.png','marks':1,'explanation':'The keyed diagram B represents an extended arrangement of sodium and chloride ions. A two-dimensional sequence alone does not show the full giant ionic lattice; use the supplied image to distinguish the diagrams.','hints':['Look for ions rather than neutral atoms.','A lattice extends in three dimensions.','Use the key in the image to identify sodium and chloride ions.']})
pack={'subtopic':SUB,'spec':'9701','version':1,'note':note,'outline':'Ionic bonding is the electrostatic attraction between positively charged cations and negatively charged anions. Metal atoms lose electrons and non-metal atoms gain electrons to form ions. In sodium chloride the ions are Na⁺ and Cl⁻; in magnesium oxide Mg²⁺ and O²⁻; in calcium fluoride Ca²⁺ and F⁻ in a 1:2 ratio. Each solid forms a giant ionic lattice, rather than separate molecules.','misconceptions':mis,'worked':[],'items':items,'flashcards':[{'id':'fc1','kc':K1,'front':'Define ionic bonding.','back':'The electrostatic attraction between oppositely charged ions (positively charged cations and negatively charged anions).'}, {'id':'fc2','kc':K2,'front':'Describe ionic bonding in sodium chloride, magnesium oxide and calcium fluoride.','back':'Na⁺ and Cl⁻, Mg²⁺ and O²⁻, and Ca²⁺ and F⁻ respectively form giant ionic lattices held by electrostatic attraction between oppositely charged ions.'}],'diagrams':[]}
out=root/'build/out/packs/9701/9701-3.2.json'
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps(pack,ensure_ascii=False,indent=2))
print(out, len(items))
